import{_ as o,o as e,c as t,a5 as d}from"./chunks/framework.BEZBAInb.js";const u=JSON.parse('{"title":"インストール","description":"","frontmatter":{"title":"インストール","order":1},"headers":[],"relativePath":"ja/2.4/konadotnet/install_konadotnet.md","filePath":"ja/2.4/konadotnet/install_konadotnet.md","lastUpdated":1788455378000}'),l={name:"ja/2.4/konadotnet/install_konadotnet.md"};function n(i,a,r,s,c,h){return e(),t("div",null,[...a[0]||(a[0]=[d('<h1 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to &quot;インストール&quot;">​</a></h1><h2 id="基本依存関係" tabindex="-1">基本依存関係 <a class="header-anchor" href="#基本依存関係" aria-label="Permalink to &quot;基本依存関係&quot;">​</a></h2><ol><li>Konado プラグインをインストールします（必須）</li><li>C# をサポートする Godot バージョン（Godot 4.6 以降を推奨）</li><li>プロジェクトを Godot .NET エディターで開いてください。通常版の Godot エディターでは C# アドオンスクリプトをコンパイルまたは読み込みできません。</li></ol><h2 id="インストール手順" tabindex="-1">インストール手順 <a class="header-anchor" href="#インストール手順" aria-label="Permalink to &quot;インストール手順&quot;">​</a></h2><ol><li>konadotnet プラグインを Godot プロジェクトの <code>addons</code> ディレクトリへ展開します</li><li><code>addons/konado</code> のメインプラグインも存在することを確認します</li><li>Godot エディターで <code>Project -&gt; Project Settings -&gt; Plugins</code> を開き、先に <code>Konado</code> を有効化します</li><li>C# プロジェクトをビルドし、MSBuild エラーがないことを確認します</li><li><code>Konadotnet</code> プラグインを有効化します</li><li>プロジェクトを開き直し、自動読み込みノードと C# スクリプト状態を更新します</li></ol><h2 id="初回有効化時のよくあるエラー" tabindex="-1">初回有効化時のよくあるエラー <a class="header-anchor" href="#初回有効化時のよくあるエラー" aria-label="Permalink to &quot;初回有効化時のよくあるエラー&quot;">​</a></h2><p>C# プロジェクトをまだビルドしていない場合、初回有効化時に次のエラーが出ることがあります。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Unable to load addon script from path: &#39;res://addons/konadotnet/Konadotnet.cs&#39;.</span></span></code></pre></div><p>Godot .NET エディターでプロジェクトをビルドし、開き直してから再度有効化してください。</p><h2 id="シーン要件" tabindex="-1">シーン要件 <a class="header-anchor" href="#シーン要件" aria-label="Permalink to &quot;シーン要件&quot;">​</a></h2><p><code>DialogueManagerAPI</code> を使うには、現在のシーンに <code>KND_DialogueManager</code> ノードが必要です。Konadotnet は次の一般的なノード名にも対応します。</p><ul><li><code>DialogManager</code></li><li><code>DialogueManager</code></li><li><code>KonadoDialogueManager</code></li></ul><p>複数の会話マネージャーがある場合は手動でバインドしてください。</p>',13)])])}const _=o(l,[["render",n]]);export{u as __pageData,_ as default};
